package com.nivor.ai;import com.nivor.ai.AiDtos.*;import com.nivor.common.exception.ResourceNotFoundException;import com.nivor.user.UserService;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class AiMemoryService{private final AiMemoryRepository repo;private final UserService users;public AiMemoryService(AiMemoryRepository r,UserService u){repo=r;users=u;}public List<MemoryView> list(String e){return repo.findAllByUser_IdOrderByUpdatedAtDesc(users.getByEmail(e).getId()).stream().limit(200).map(this::view).toList();}public MemoryView create(String e,MemoryRequest r){AiMemory m=new AiMemory();m.setUser(users.getByEmail(e));apply(m,r);return view(repo.save(m));}public MemoryView update(String e,long id,MemoryRequest r){AiMemory m=owned(e,id);apply(m,r);return view(m);}public void delete(String e,long id){repo.delete(owned(e,id));}private AiMemory owned(String e,long id){return repo.findByIdAndUser_Id(id,users.getByEmail(e).getId()).orElseThrow(()->new ResourceNotFoundException("Memory not found"));}private void apply(AiMemory m,MemoryRequest r){m.setCategory(r.category().trim());m.setContent(r.content().trim());m.setImportance(r.importance());}private MemoryView view(AiMemory m){return new MemoryView(m.getId(),m.getCategory(),m.getContent(),m.getImportance(),m.getCreatedAt());}}
